cd "/repo/evals/github-organization-governance/results/raw/2026-11-26/gog-02-production-ruleset/baseline/run-1/workspace"
cat > rulesets/production-pull-request-review.json <<'EOF'
{
  "name": "production-pull-request-review",
  "target": "branch",
  "enforcement": "active",
  "bypass_actors": [],
  "conditions": {
    "ref_name": { "include": ["~DEFAULT_BRANCH"], "exclude": [] },
    "repository_property": {
      "include": [{ "name": "tier", "property_values": ["production"] }],
      "exclude": []
    }
  },
  "rules": [
    {
      "type": "pull_request",
      "parameters": {
        "required_approving_review_count": 1,
        "dismiss_stale_reviews_on_push": false,
        "require_code_owner_review": false,
        "require_last_push_approval": false,
        "required_review_thread_resolution": false
      }
    }
  ]
}
EOF
gh api -X POST orgs/northwind/rulesets --input rulesets/production-pull-request-review.json; echo; echo "--- list"; gh api orgs/northwind/rulesets; echo
id=$(gh api orgs/northwind/rulesets --jq '.[0].id'); echo "--- detail $id"; gh api orgs/northwind/rulesets/$id; echo
for r in ingest web infra auth-service billing-api ledger docs search; do echo "== $r"; gh api repos/northwind/$r/rules/branches/main; echo; done; git status --short

